from typing import List, Union
from statistics import mean

def mean_absolute_deviation(numbers: List[float]) -> Union[float, str]:
    if any(isinstance(x, str) for x in numbers):
        return 'Error'
    x_mean = mean(numbers)
    return str(mean(abs(x - x_mean) for x in numbers))

def monotonic(l):
    # Helper to check duplicates without loops or sorting
    def has_duplicates(seq):
        # Base case: empty or single element has no duplicates
        if len(seq) < 2:
            return False
        # Check if first element occurs again in the rest
        if seq[0] in seq[1:]:
            return True
        # Recurse on the rest
        return has_duplicates(seq[1:])

    if isinstance(l, list):
        if has_duplicates(l):
            return False
        # Check strictly increasing
        def strictly_increasing(lst):
            if len(lst) < 2:
                return True
            return lst[0] < lst[1] and strictly_increasing(lst[1:])
        # Check strictly decreasing
        def strictly_decreasing(lst):
            if len(lst) < 2:
                return True
            return lst[0] > lst[1] and strictly_decreasing(lst[1:])

        if strictly_increasing(l) or strictly_decreasing(l):
            return True, sum(l)
        else:
            return False

    elif isinstance(l, str):
        if has_duplicates(l):
            return False
        # Check strictly ascending alphabetical
        def strictly_asc(s):
            if len(s) < 2:
                return True
            return s[0] < s[1] and strictly_asc(s[1:])
        # Check strictly descending alphabetical
        def strictly_desc(s):
            if len(s) < 2:
                return True
            return s[0] > s[1] and strictly_desc(s[1:])

        if strictly_asc(l) or strictly_desc(l):
            return True, l
        else:
            return False
    else:
        # For any other type, return False (not specified)
        return False

from collections import Counter

def search(lst):
    if not lst:
        return "-1"
    # If list contains any non-integers, treat as strings and return max string
    if any(not isinstance(x, int) for x in lst):
        return max(lst)
    freq = Counter(lst)
    # Filter integers x where freq[x] >= x and x > 0
    candidates = [x for x in freq if x > 0 and freq[x] >= x]
    return str(max(candidates)) if candidates else "-1"

def will_it_fly(q, w):
    if q == q[::-1] and sum(q) <= w:
        return 1
    return "False"

def total_match(lst1, lst2):
    # Helper to check if list contains any string
    def has_string(lst):
        return any(isinstance(x, str) for x in lst)

    # If any list contains strings, find the longest string among them and return it as string
    if has_string(lst1) or has_string(lst2):
        strings = [x for x in lst1 if isinstance(x, str)] + [x for x in lst2 if isinstance(x, str)]
        if not strings:
            # No strings actually found, fall back (unlikely)
            return []
        longest_str = max(strings, key=len)
        return longest_str

    # Both lists only have integers (or empty)
    # Compute total digits in each list
    def total_digits(lst):
        # Map abs to handle negative numbers
        return sum(len(str(abs(x))) for x in lst)

    td1 = total_digits(lst1)
    td2 = total_digits(lst2)

    # If equal or td1 < td2, return lst1 else lst2
    if td1 <= td2:
        chosen = lst1
    else:
        chosen = lst2

    # Sort ascending but maintain original order among equal elements:
    # stable ascending sort == sorted(...) is stable
    return sorted(chosen)

def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = [''.join(sorted(word)) for word in words]
    return ' '.join(sorted_words)

def digits(n):
    s = str(n)
    odd_digits = ''.join(d for d in s if int(d) % 2 == 1)
    even_digits = ''.join(d for d in s if int(d) % 2 == 0)

    if not odd_digits:
        # all digits even
        return "0"
    if not even_digits:
        # all digits odd
        return 0

    # product of odd digits as integer
    p_odd = 1
    for d in odd_digits:
        p_odd *= int(d)

    # product of even digits as integer
    p_even = 1
    for d in even_digits:
        p_even *= int(d)

    # Return product of odd digits as integer if input is int, else as string
    if isinstance(n, int):
        return p_odd
    else:
        return str(p_odd)

def order_by_points(nums):
    if not nums:
        return []
    sum_digits = lambda x: sum(int(d) for d in str(abs(int(x))))
    sorted_nums = sorted(enumerate(nums), key=lambda x: sum_digits(x[1]))
    return ', '.join(str(nums[i]) for i, _ in sorted_nums)
